  const r=state.result;
  target.innerHTML='<div class="rpa-controls"><div>'+select('family','浏览本次返回的矩阵族',FAMILIES.map(k=>[k,familyName(k)]),state.family)+'</div><div>'+select('operation-left','左因子 g（后作用）',IDS.map(k=>[k,k]),state.left)+'</div><div>'+select('operation-right','右因子 h（先作用）',IDS.map(k=>[k,k]),state.right)+'</div><div>'+select('frame','浏览返回的操作帧',[['0','起始坐标'],['1','作用 h 后'],['2','再作用 g 后']],state.frameIndex)+'</div></div><p>这些选择只读取本次完整回包；不会重新启动计算，也不会改动原有点群输入。</p><div class="rpa-stage-controls"><button id="rpa-next" class="secondary" type="button"'+(state.stage>=5?' disabled':'')+'>展开表示下一步</button><button id="rpa-first" class="secondary" type="button">回到表示第一步</button><span id="rpa-stage-status" role="status">表示核验步骤 '+state.stage+' / 5 步</span></div>'+representationActionsResultHTML(r,state)+'<details data-rpa-native="checks"'+(state.details.checks?' open':'')+'><summary>展开计算核验与来源</summary><p>计算核验应全部通过；混用矩阵表中失败的乘法对则是故意保留的教学反例。</p><ul class="rpa-checks">'+r.checks.map(c=>'<li>'+esc(c.id)+' · 核验通过</li>').join('')+'</ul><ul>'+r.sources.map(s=>'<li><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a></li>').join('')+'</ul></details>'+(typeof download==='function'?'<button id="rpa-export" class="secondary" type="button">独立导出表示输入与完整账本</button>':'');
  bind('next','onclick',()=>{state.stage=Math.min(5,state.stage+1);drawResult();});bind('first','onclick',()=>{state.stage=1;drawResult();});
  for(const [name,key,ids]of [['family','family',FAMILIES],['operation-left','left',IDS],['operation-right','right',IDS]])bind(name,'onchange',node=>{if(ids.includes(node.value)){state[key]=node.value;drawResult();}});
