  bind('export','onclick',()=>{if(state.result===r&&requestValid(state.input))download(JSON.stringify({kind:'representation-actions-teaching',lessonId,input:state.input,result:r},null,2),'representation-actions-ledger.json','application/json');});
  const node=$('drawing-path');if(node){const choices={family:state.family,left:state.left,right:state.right,frameIndex:state.frameIndex},render=()=>{if(active()&&state.result===r&&$('drawing-path')===node)node.innerHTML=representationActionsDrawingHTML(r,{...choices,width:node.clientWidth||340});};render();if(typeof ResizeObserver==='function'){const observer=new ResizeObserver(render);observer.observe(node);observers.push(observer);}}
